"use strict";

import Selectable from "approot/global/selectable";
import * as AddServicesRefs from "../refs.js";
import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

export class EditAddServiceCtrl extends NetCityModalController {
	/*@ngInject*/
	constructor(pageContext, $scope, addServicesRepository, $dialogs, $appLoader, $uibModalInstance, addService, mode, changeTracker) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);

		this.addServicesRepository = addServicesRepository;
		this.uibModalInstance = $uibModalInstance;
		this.appLoader = $appLoader;

		this.mode = mode;
		this.header = mode.edit ? "Редактировать дополнительную услугу" : "Добавить дополнительную услугу"

		this.language = language;

		this.state = {
			dataReady: false,
			emptyData: false,
			viewReady: true,
			contentWasChanged: false
		}

		this.data = {
			addService: addService,
			selection: new Selectable(),
			addServiceTypes: AddServicesRefs.default.addServicesTypes
		}

		this.load();
	}

	cancel() {
		this.uibModalInstance.dismiss("cancel");
	}

	save(valid, addService) {
		if (valid) {
			if (addService) {
				this.addServicesRepository.edit(addService)
					.then((addService) => {
						this.state.dataReady = true;
						this.appLoader.hide();
						this.uibModalInstance.close(addService);
					});
			}
			else {
				this.addServicesRepository.create(this.data.addService.item).then((addService) => {
					this.appLoader.hide();
					if (addService) {
						this.state.dataReady = true;
						this.mode.edit = true;
						this.mode.create = false;
						this.data.addService.item = addService;
						this.uibModalInstance.close(addService);
					}
				});
			}
		}
	}

	load() {
		this.addServicesRepository.getStaffList(appContext.yearId, this.data.addService ? this.data.addService.item : null)
			.then((staffList) => {
				this.data.users = staffList;
				this.appLoader.hide();
			});
	}
}


