"use strict";

import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

export class EditRefItemCtrl extends NetCityModalController {
	/*@ngInject*/
	constructor($scope, refBookRepository, refType, refItem, $uibModalInstance, $dialogs, changeTracker) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);
		this.refBookRepository = refBookRepository;
		this.refType = refType;
		this.refItem = refItem;
		this.uibModalInstance = $uibModalInstance;

		this.language = language;
		this.data = {
			refType: refType,
			refItem: refItem
		};

		if (refItem.id) {
			this.header = language.Generic.SetupSchool.kPageTitle_Edit + " \"" + refType.name + "\"";
		} else {
			this.header = language.Generic.SetupSchool.kPageTitle_New + " \"" + refType.name + "\"";
		}
	}

	save() {
		if (!this.data.refItem.name.trim()) {
			alert("Необходимо заполнить полное название");
			return;
		}
		this.refBookRepository.saveRefItems(this.refType.refType, this.data.refItem, this.refType.parameterId)
			.then((item) => {
				if (!item) {
					return;
				}
				this.uibModalInstance.close(this.data.refItem);
			});
	}

	cancel() {
		this.uibModalInstance.dismiss('cancel');
	}
}


