"use strict";

import Selectable from "approot/global/selectable";

export class AddServiceListCtrl {
	/*@ngInject*/
	constructor(pageContext, $appLoader, $uibModal, addServicesRepository) {
		this.appLoader = $appLoader;
		this.uibModal = $uibModal;
		this.addServicesRepository = addServicesRepository;
		pageContext.title = language.Generic.MenuFolders.kAddServices;

		angular.extend(this,
			{
				paging: {
					page: 1,
					pageSize: 20,
					totalcount: 0
				}
			});


		this.language = language;
		this.data = {
			addServices: [],
			selection: new Selectable()
		};
		this.state = {
			dataReady: false,
			emptyData: false,
			viewReady: true,
			readOnlyContext: appContext.readOnly
		};

		this.load();
	}

	//редактировать
	editService(addService) {
		let modalInstance = this.uibModal.open({
			templateUrl: '/static/dist/app/school/orginfo/addservices/edit/template.html',
			controller: 'EditAddServiceCtrl as ctrl',
			backdrop: false,
			resolve: {
				addService: () => angular.copy(addService),
				mode: () => new Object({ edit: true })
			}
		});
		modalInstance.result.then(() => this.load());
		modalInstance.closed.then(() => this.load());
	}

	//добавить
	addService(addService) {
		let modalInstance = this.uibModal.open({
			templateUrl: '/static/dist/app/school/orginfo/addservices/edit/template.html',
			controller: 'EditAddServiceCtrl as ctrl',
			backdrop: false,
			resolve: {
				addService: addService,
				mode: () => new Object({ create: true })
			}
		});
		modalInstance.result.then(() => this.load());
		modalInstance.closed.then(() => this.load());
	}

	//удалить
	removeService(addService) {
		$.show.confirmation(`Удалить дополнительную услугу "${addService.name}"?`.escapeHTML())
			.then(() => {
				this.addServicesRepository.remove(addService.id)
					.then(() => {
						this.load();
					});
			});
	}

	//загрузка данных
	load() {
		const params = {
			page: this.paging.page,
			pageSize: this.paging.pageSize
		};
		this.addServicesRepository.getAll(params)
			.then((addServices) => {
				// paging
				this.paging.totalcount = addServices.totalcount;
				this.paging.show = this.paging.totalcount > this.paging.pageSize && this.paging.page > 0;

				this.data.addServices = addServices;
				this.data.selection.selected = false;
				this.state.emptyData = !addServices.length;
				this.state.dataReady = true;
				this.appLoader.hide();
			});
	}
}


