"use strict";

export class SettingsListCtrl {
	/*@ngInject*/
	constructor(pageContext, $appLoader, schoolSettingsRepository, $uibModal, $alerts, $q, $dialogs, changeTracker) {
		this.schoolSettingsRepository = schoolSettingsRepository;
		this.appLoader = $appLoader;
		this.uibModal = $uibModal;
		this.changeTracker = changeTracker;
		this.alerts = $alerts;
		this.dialogs = $dialogs;
		this.$q = $q;

		pageContext.title = language.MenuFolders.kFNSchoolSettings;
		this.language = language;

		this.state = {
			dataReady: false
		};

		this.data = {
			schoolSettings: {},
			grades: appContext.funcType === 1
				? [{ id: 0, name: language.Generic.Common.kGr0_s },
				{ id: 1, name: language.Generic.Common.kGr1_s },
				{ id: 2, name: language.Generic.Common.kGr2_s },
				{ id: 3, name: language.Generic.Common.kGr3_s },
				{ id: 4, name: language.Generic.Common.kGr4_s },
				{ id: 5, name: language.Generic.Common.kGr5_s },
				{ id: 6, name: language.Generic.Common.kGr6_s },
				{ id: 7, name: language.Generic.Common.kGr7_s },
				{ id: 8, name: language.Generic.Common.kGr8_s }]
				: [{ id: 0, name: "0" },
				{ id: 1, name: "1" },
				{ id: 2, name: "2" },
				{ id: 3, name: "3" },
				{ id: 4, name: "4" },
				{ id: 5, name: "5" },
				{ id: 6, name: "6" },
				{ id: 7, name: "7" },
				{ id: 8, name: "8" },
				{ id: 9, name: "9" },
				{ id: 10, name: "10" },
				{ id: 11, name: "11" },
				{ id: 12, name: "12" }],
			funcType: appContext.funcType,
			windowsAuth: false,
			oldMinMark: null,
			oldMaxMark: null
		};

		this.load();
	}

	load() {
		this.state.dataReady = false;
		const getSchoolSettings = this.schoolSettingsRepository.getSchoolSettings().then((settings) => {
			this.data.schoolSettings = settings;
			this.data.oldMinMark = this.data.schoolSettings.minMark;
			this.data.oldMaxMark = this.data.schoolSettings.maxMark;
		});
		const getWindowsAuth = this.schoolSettingsRepository.getWindowsAuth().then((windowsAuth) => {
			this.data.windowsAuth = windowsAuth;
		});
		let waits = [getSchoolSettings, getWindowsAuth];
		this.$q.all(waits).then(() => {
			this.state.dataReady = true;
			this.appLoader.hide();
		});
	}

	saveExecute() {
		this.appLoader.show();
		this.schoolSettingsRepository.saveSchoolSettings(this.data.schoolSettings)
			.then((result) => {
				this.appLoader.hide();
				this.data.schoolSettings = angular.copy(result);
				this.data.oldMinMark = this.data.schoolSettings.minMark;
				this.data.oldMaxMark = this.data.schoolSettings.maxMark;
				this.changeTracker.clearDataChanges();
				this.alerts.success(this.language.Generic.SchoolSettings.kTitleSettings +
					this.language.Common.kOfSchool +
					this.language.Generic.SchoolSettings.kSuccessfulSaved);
			});
	}

	save(valid) {
		var juniorRange = { start: this.data.schoolSettings.juniorStepGrade.start, end: this.data.schoolSettings.juniorStepGrade.end }
		var middleRange = { start: this.data.schoolSettings.middleStepGrade.start, end: this.data.schoolSettings.middleStepGrade.end }
		var seniorRange = { start: this.data.schoolSettings.seniorStepGrade.start, end: this.data.schoolSettings.seniorStepGrade.end }
		if (valid
			&& this.isValidRange(juniorRange)
			&& this.isValidRange(middleRange)
			&& this.isValidRange(seniorRange)
			&& !this.isIntersectedGradesRanges()
			&& !this.isGradesRangesWrongOrder()
			&& !this.emptySpaceBetweenRanges()
		) {
			if (this.data.schoolSettings.minMark !== this.data.oldMinMark ||
				this.data.schoolSettings.maxMark !== this.data.oldMaxMark) {
				this.dialogs
					.confirm(this.language.Generic.SchoolSettings.kConChangeMarkRange)
					.then(() => {
						this.saveExecute();
					});
			} else {
				this.saveExecute();
			}
		}
	}

	enabledMaxMark() {
		if (+settingsForm.MinMark.value && !this.data.schoolSettings.minMark) {
			this.data.schoolSettings.minMark = +settingsForm.MinMark.value;
		}
		if (+settingsForm.MaxMark.value && !this.data.schoolSettings.maxMark) {
			this.data.schoolSettings.maxMark = +settingsForm.MaxMark.value;
		}
		let minMark = Math.min(this.data.schoolSettings.minMark || +settingsForm.MinMark.value, 99);
		let maxMark = this.data.schoolSettings.maxMark || +settingsForm.MaxMark.value;

		return minMark && minMark >= 1 && minMark < 100 && maxMark <= minMark
			? minMark + 1
			: (maxMark || 1) > 100
				? (minMark || 1) + 1
				: (maxMark || 1);
	}

	enabledMinMark() {
		if (+settingsForm.MaxMark.value && !this.data.schoolSettings.maxMark) {
			this.data.schoolSettings.maxMark = +settingsForm.MaxMark.value;
		}
		if (+settingsForm.MinMark.value && !this.data.schoolSettings.minMark) {
			this.data.schoolSettings.minMark = +settingsForm.MinMark.value;
		}
		let minMark = this.data.schoolSettings.minMark || +settingsForm.MinMark.value;
		let maxMark = Math.min(this.data.schoolSettings.maxMark || +settingsForm.MaxMark.value, 100);
		return maxMark && maxMark > 1 && maxMark <= 100 && minMark >= maxMark
			? maxMark - 1
			: Math.min(minMark, 99) || (maxMark || 100) - 1;
	}

	isValidRange(range) {
		return range.end >= range.start;
	}

	isIntersectedOrInvalidRanges(firstRange, secondRange) {
		return !(this.isValidRange(firstRange) && this.isValidRange(secondRange) && (firstRange.end < secondRange.start || secondRange.end < firstRange.start));
	}

	isIntersectedGradesRanges() {
		if (this.data.schoolSettings.juniorStepGrade && this.data.schoolSettings.middleStepGrade && this.data.schoolSettings.seniorStepGrade) {
			var juniorRange = { start: this.data.schoolSettings.juniorStepGrade.start, end: this.data.schoolSettings.juniorStepGrade.end }
			var middleRange = { start: this.data.schoolSettings.middleStepGrade.start, end: this.data.schoolSettings.middleStepGrade.end }
			var seniorRange = { start: this.data.schoolSettings.seniorStepGrade.start, end: this.data.schoolSettings.seniorStepGrade.end }
			return this.isValidRange(juniorRange)
				&& this.isValidRange(middleRange)
				&& this.isValidRange(seniorRange)
				&& (this.isIntersectedOrInvalidRanges(juniorRange, middleRange)
					|| this.isIntersectedOrInvalidRanges(juniorRange, seniorRange)
					|| this.isIntersectedOrInvalidRanges(seniorRange, middleRange));
		} else { return false; }
	}

	emptySpaceBetweenRanges() {
		if (this.data.schoolSettings.juniorStepGrade &&
			this.data.schoolSettings.middleStepGrade &&
			this.data.schoolSettings.seniorStepGrade) {
			return this.data.schoolSettings.juniorStepGrade.end !== (this.data.schoolSettings.middleStepGrade.start - 1)
				|| this.data.schoolSettings.middleStepGrade.end !== (this.data.schoolSettings.seniorStepGrade.start - 1);
		} else {
			return false;
		}
	}

	isGradesRangesWrongOrder() {
		if (this.data.schoolSettings.juniorStepGrade && this.data.schoolSettings.middleStepGrade && this.data.schoolSettings.seniorStepGrade) {
			return this.data.schoolSettings.juniorStepGrade.start >= this.data.schoolSettings.middleStepGrade.start ||
				this.data.schoolSettings.juniorStepGrade.start >= this.data.schoolSettings.seniorStepGrade.start ||
				this.data.schoolSettings.middleStepGrade.start >= this.data.schoolSettings.seniorStepGrade.start;
		} else {
			return false;
		}
	}

	weights() {
		const modalInstance = this.uibModal.open({
			templateUrl: "/static/dist/app/school/orginfo/settings/edit/editAssignmentTypeWeightsTemplate.html",
			controller: 'AssignmentTypeWeightsController as ctrl',
			size: "md",
			resolve: {
			}
		});

		modalInstance.rendered.then(() => {
		});

		modalInstance.result.then((options) => resolve(options));
	}
}


