"use strict";

import { BaseRepository } from "approot/global/repository/baseRepository";
import { AppContext } from "approot/global/services/context";
import { DialogsService, LongWorkService } from "approot/global/providers/uikit.dialogs";
import { SchoolSettingDto } from "./schoolsettings.model";

export class SchoolSettingsRepository extends BaseRepository {
	/*@ngInject*/
	constructor($http, $dialogs: DialogsService, $longWork: LongWorkService, private appContext: AppContext) {
		super($http, $dialogs, $longWork);
	}

	getSchoolSettings() : Promise<SchoolSettingDto> {
		return this.$http.get(`/webapi/school/settings`, { params: { yearId: this.appContext.yearId } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	saveSchoolSettings(schoolSettings) {
		return this.$http.post(`/webapi/school/settings`, schoolSettings)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getWindowsAuth() {
		return this.$http.get(`/webapi/settings/windowsAuth`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getAssignmentTypes() {
		return this.$http.get(`/webapi/grade/assignment/types`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getAssignmentTypesWeights() {
		return this.$http.get(`/webapi/grade/journal/assignments/types/weights`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	saveAssignmentTypesWeights(weights) {
		return this.$http.post(`/webapi/grade/journal/assignments/types/weights`, weights)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

}



