"use strict";

export class RefBookCtrl {
	/*@ngInject*/
	constructor(pageContext, $appLoader, refBookRepository, $uibModal) {
		this.refBookRepository = refBookRepository;
		this.appLoader = $appLoader;
		this.uibModal = $uibModal;

		this.language = language;

		this.state = {
			dataReady: false,
			emptyData: false
		};
		this.data = {
			refType: null,
			checked: [],
			refTypes: [],
			refItems: []
		}

		pageContext.title = language.Generic.SetupSchool.kTitleRefBooks;

		refBookRepository.getRefs().then((refTypes) => {
			this.data.refTypes = _.map(refTypes, (item) => {
				item.id = item.refType + item.parameterId;
				return item;
			});
			this.data.refType = refTypes[0];
		}).then(() => {
			this.load();
		});
	}

	toggleChecks(id) {
		var idx = this.data.checked.indexOf(id);
		if (idx > -1) {
			this.data.checked.splice(idx, 1);
		}
		else {
			this.data.checked.push(id);
		}
	}

	add() {
		this.edit({ name: "", shortName: "" });
	};

	edit(refItem) {
		let modalInstance = this.uibModal.open({
			templateUrl: "/static/dist/app/school/orginfo/refbook/edit/template.html",
			controller: "EditRefItemCtrl as ctrl",
			resolve: {
				refType: () => this.data.refType,
				refItem: () => angular.copy(refItem)
			}
		});
		modalInstance.result.then(() => {
			this.load();
		});
	};

	//todo. обработку чекбокса

	delete() {
		$.show.confirmation(language.Generic.Common.kMsgAreYouSure)
			.then(() => {
				this.refBookRepository.deleteRefItems(this.data.refType.refType, this.data.checked).then(() => {
					this.load();
				});
			});
	};

	//загрузка данных
	load() {
		this.state.dataReady = false;

		this.refBookRepository
			.getRefItems(this.data.refType.refType, this.data.refType.parameterId)
			.then((refItems) => {
				this.data.checked = [];
				this.appLoader.hide();
				this.data.refItems = refItems;
				this.state.dataReady = true;
				this.state.emptyData = this.data.refItems.length === 0;
			});
	}
}


