"use strict";

import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";

export class AssignmentTypeWeightsController extends NetCityModalController {
	/*@ngInject*/
	constructor($scope, $uibModalInstance, $alerts, $q, $appLoader, $dialogs, schoolSettingsRepository, changeTracker) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);
		this.schoolSettingsRepository = schoolSettingsRepository;
		this.uibModalInstance = $uibModalInstance;
		this.alerts = $alerts;
		this.changeTracker = changeTracker;
		this.appLoader = $appLoader;
		this.$q = $q;

		this.language = language;

		this.header = language.Generic.SchoolSettings.kAssignmentTypeWeightsSetup;

		this.data = {
			assignmentTypes: [],
			assignmentTypesWeights: [],
			weights: []
		};

		this.state = {
			dataReady: false
		}

		this.messages = {
			from1Before100: language.Generic.Messages.kIntFromBefore.replace(/\{(\d+)\}/g, (match, index) => Array.prototype.slice.call([0, 100], 0)[index])
		}

		this.load();
	}

	cancel() {
		this.uibModalInstance.dismiss("cancel");
	}

	save(valid) {
		if (valid) {
			this.schoolSettingsRepository.saveAssignmentTypesWeights(_.map(this.data.weights, (item) => { return { assignmentTypeId: item.id, schoolId: +appContext.schoolId, weight: item.weight } })).then(() => {
				this.changeTracker.clearDataChanges($("div.modal.fade"));
				this.alerts.success(this.language.Generic.Assignment.kAssignmentTypesWeightsWasSaved);
				this.cancel();
			});
		}
	}

	load() {
		this.state.dataReady = false;
		const getAssignmentTypes = this.schoolSettingsRepository.getAssignmentTypes().then((types) => {
			this.data.assignmentTypes = types;
		});
		const getAssignmentTypesWeights = this.schoolSettingsRepository.getAssignmentTypesWeights().then((weights) => {
			this.data.assignmentTypesWeights = weights;
		});
		let waits = [getAssignmentTypes, getAssignmentTypesWeights];
		this.$q.all(waits).then(() => {
			this.data.weights = _.chain(this.data.assignmentTypes)
				.map(item => { return { id: item.id, name: item.name, weight: (_.find(this.data.assignmentTypesWeights, (wt) => wt.assignmentTypeId === item.id) || { assignmentTypeId: item.id, weight: 10 }).weight } })
				.sortBy(item => item.order)
				.toArray()
				.value();
			this.state.dataReady = true;
			this.appLoader.hide();
		});
	}
}


