"use strict";

import { BaseRepository } from "approot/global/repository.js";

export class RefBookRepository extends BaseRepository {
	getRefs() {
		return this.$http.get("/webapi/refbook")
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	getRefItems(refType, parameterId) {
		let params = {};
		if (parameterId) {
			params.parameterId = parameterId;
		}
		return this.$http.get(`/webapi/refbook/${refType}`, {params})
			.then((response) => {
				return response.data;
			})
			.catch(this.handleError);
	}

	saveRefItems(refType, item, parameterId) {
		let params = {};
		if (parameterId) {
			params.parameterId = parameterId;
		}
		return this.$http.post(`/webapi/refbook/${refType}`, item, {params})
			.then(() => {
				this.$alerts.success("Справочник успешно сохранен");
				return item;
			}, this.handleError);
	}

	deleteRefItems(refType, id) {
		let params = { id };
		return this.$http.delete(`/webapi/refbook/${refType}`, {params})
			.then((response) => {
				this.$alerts.success("Значения справочника успешно удалены");
				return response.data;
			})
			.catch(this.handleError);
	}
}


