const module = angular
	.module("irtech.netcity.school.orginfo",
		[
			"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
			"ngFileUpload", "ui.tree", "irtech.netcity.common", "irtech.netcity.ui-components"
		]);

import { AddServiceListCtrl } from "./addservices/list/addServicesListCtrl.js";
import { EditAddServiceCtrl } from "./addservices/edit/editAddServiceCtrl.js";
import { AddServicesRepository } from "./addservices/repository.js";

import { RefBookCtrl } from "./refbook/list/refbookCtrl.js";
import { EditRefItemCtrl } from "./refbook/edit/editRefItemCtrl.js";
import { RefBookRepository } from "./refbook/repository.js";

import { SettingsListCtrl } from "./settings/list/settingsListCtrl.js";
import { AssignmentTypeWeightsController } from "./settings/edit/assignmentTypeWeightsCtrl.js";
import { SchoolSettingsRepository } from "./settings/schoolsettings.repository";

import { MaintenanceCtrl } from "./maintenance/maintenanceCtrl.js";
import { MaintenanceRepository } from "./maintenance/repository.js";

module
	.service("schoolSettingsRepository", SchoolSettingsRepository)
	.service("refBookRepository", RefBookRepository)
	.service("addServicesRepository", AddServicesRepository)
	.service("maintenanceRepository", MaintenanceRepository)
	.controller("AddServiceListCtrl", AddServiceListCtrl)
	.controller("EditAddServiceCtrl", EditAddServiceCtrl)
	.controller("MaintenanceCtrl", MaintenanceCtrl)
	.controller("EditRefItemCtrl", EditRefItemCtrl)
	.controller("SettingsListCtrl", SettingsListCtrl)
	.controller("AssignmentTypeWeightsController", AssignmentTypeWeightsController)
	.controller("RefBookCtrl", RefBookCtrl)
	.directive('yrInteger', function () {
		return {
			restrict: 'A',
			link: function (scope, element, attrs) {
				element.on('keypress',
					function (event) {

						if (!isIntegerChar())
							event.preventDefault();

						function isIntegerChar() {
							return /[0-9]/.test(
								String.fromCharCode(event.which));
						}

					});
			}
		}
	})
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/addservices/", {
				templateUrl: "/static/dist/app/school/orginfo/addservices/list/template.html",
				controller: "AddServiceListCtrl as ctrl"
			})
			.when("/refbook/", {
				templateUrl: "/static/dist/app/school/orginfo/refbook/list/template.html",
				controller: "RefBookCtrl as ctrl"
			})
			.when("/refbook/edit/", {
				templateUrl: "/static/dist/app/school/orginfo/refbook/edit/template.html",
				controller: "EditRefItemCtrl as ctrl"
			})
			.when("/settings/", {
				templateUrl: "/static/dist/app/school/orginfo/settings/list/template.html",
				controller: "SettingsListCtrl as ctrl"
			})
			.when("/maintenance/", {
				templateUrl: "/static/dist/app/school/orginfo/maintenance/template.html",
				controller: "MaintenanceCtrl as ctrl"
			})
			.otherwise({
				templateUrl: "/static/dist/app/school/orginfo/settings/list/template.html",
				controller: "SettingsListCtrl as ctrl"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});




