"use strict";

import { BaseRepository } from "approot/global/repository.js";

class MaintenanceRepository extends BaseRepository {
	getMaintenance() {
		return this.$http.get("/webapi/school/maintenance").then((response) => {
			return response.data;
		})
		.catch(this.handleError);
	}

	save(maintenance) {
		return this.$http.post("/webapi/school/maintenance", maintenance)
		.catch(this.handleError);
	}
}

module.exports = { MaintenanceRepository };



